@pytest.fixture
def lesson():
    spec = importlib.util.spec_from_file_location('numeric_transfer_worksheet', LESSON)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def numeric_case(lesson):
    case = deepcopy(LEGACY_V1_COMPLETED['case'])
    case.update(section='99.2', title='Distinct synthetic numeric transfer fixture',
                transfer='Synthetic numeric quantity after a changed fixture condition.',
                transfer_prediction_type='numeric')
    return case


def observed_fixture(lesson, case):
    # Exact JSON-native source hashes are fabricated; no source files or methods run.
    config = deepcopy(LEGACY_V1_COMPLETED['config'])
    record = lesson.commit_prediction(case, config, 0.125, 0.5, 'Synthetic rationale only.')
    measured = lesson.record_observation(record, config, 0.25, {'synthetic control': 0},
        'historical_reference', 'Synthetic fixture only; not a measured result.')
    return config, record, measured


def completed_fixture(lesson):
    case = numeric_case(lesson)
    config, record, observed = observed_fixture(lesson, case)
    completed = lesson.reflect(observed, 'Synthetic mismatch.', 'Synthetic changed condition.',
                               0.375, 0.4, 'Synthetic transfer rationale.')
    return case, config, record, observed, completed


@pytest.mark.parametrize('prediction', [0, -3, 0.375, -0.0, 10 ** 400])
def test_numeric_transfer_full_portable_lifecycle(lesson, tmp_path, prediction):
    case = numeric_case(lesson)
    config, committed, observed = observed_fixture(lesson, case)
    before = deepcopy((committed, observed))
    completed = lesson.reflect(observed, 'Synthetic mismatch.', 'Synthetic changed condition.',
                               prediction, 0.4, 'Synthetic transfer rationale.')
    assert (committed, observed) == before
    assert completed['schema_version'] == lesson.VERSION
    assert type(completed['transfer']['prediction']) is type(prediction)
    assert completed['transfer']['prediction'] == prediction
    assert completed['transfer']['status'] == 'forecast_only'
    path = lesson.export_record(completed, tmp_path / 'private-numeric-fixture')
    loaded = lesson.load_record(path)
    assert loaded == completed
    assert lesson.loads_record(lesson.dumps_record(loaded)) == completed
    assert lesson.replay_record(loaded) == {
        'verification': 'learner_reported', 'executed': False, 'record': completed}
    transferred = lesson.transfer_case(loaded)
    assert transferred['prediction_type'] == 'numeric'
    assert transferred['forecast_items'] == []
    assert transferred['question'] == case['transfer']
    for key in case.keys() - {'title', 'question', 'prediction_type', 'forecast_items'}:
        assert transferred[key] == case[key]
    changed_config = deepcopy(config)
    changed_config['inputs']['fixture'] = 'distinct synthetic changed condition'
    new = lesson.commit_prediction(transferred, changed_config, prediction, 0.4,
                                   'Synthetic transfer rationale.')
    assert new['record_id'] != completed['record_id']
    assert new['config_fingerprint'] != completed['config_fingerprint']
    assert new['status'] == 'committed' and new['observation'] is None
    assert completed['status'] == 'completed'
    assert loaded == completed


@pytest.mark.parametrize('bad', [True, False, None, '0.375', [], {}, float('nan'),
                                float('inf'), float('-inf')])
def test_numeric_transfer_rejects_wrong_types_and_nonfinite(lesson, bad):
    _, _, observed = observed_fixture(lesson, numeric_case(lesson))
    before = deepcopy(observed)
    with pytest.raises(ValueError):
        lesson.reflect(observed, 'Synthetic mismatch.', 'Synthetic changed condition.',
                       bad, 0.4, 'Synthetic rationale.')
    assert observed == before


